const KILLED: Record<string, number> = { Rat: 1, Man: 2, Woman: 2 };
const SKIP = new Set(Object.keys(KILLED));
const wantAt = (x: number, z: number) => {
  const st = sdk.getState();
  const cb = st.player.combatLevel;
  let best: any = null;
  for (const n of st.nearbyNpcs) {
    if (SKIP.has(n.name)) continue;
    if (!n.reachable) continue;
    if (!n.optionsWithIndex.some(o => /attack/i.test(o.text))) continue;
    if ((n.combatLevel ?? 0) > cb + 2) continue;
    const d = Math.abs(n.x - x) + Math.abs(n.z - z);
    const score = (Math.log(1 + (n.combatLevel ?? 0)) * 10) - d * 0.5;
    if (!best || score > best.score) best = { score, npc: n };
  }
  return best ? best.npc : null;
}
async function lootFood() {
  try {
    const items = await sdk.scanGroundItems();
    const f = items.filter(i => /raw chicken|raw beef|leg|shrimps|bones/i.test(i.name) && i.distance < 8).slice(0, 2);
    for (const i of f) await bot.pickupItem(i);
  } catch {}
}
async function stayAlive() {
  const s = sdk.getState();
  if (s.player.hitpoints <= Math.max(5, (s.player.hitpoints ?? 10) * 0.5) || s.player.hitpoints < 8) {
    const r = await bot.eatFood(/raw chicken|raw beef|bread|shrimps|monk/i).catch(() => null);
    if (r && r.success) console.log('ate', r.message);
  }
}
const waypoints: [number, number][] = [[3217, 3226], [3192, 3207], [3202, 3253], [3165, 3247], [3235, 3259], [3254, 3258], [3225, 3300], [3227, 3290]];
const log: string[] = [];
const stop = Date.now() + 210_000;
for (const [wx, wz] of waypoints) {
  if (Date.now() > stop) break;
  await bot.walkTo(wx, wz, 4, { timeout: 40_000 }).catch(() => {});
  for (let iter = 0; iter < 6 && Date.now() < stop; iter++) {
    const npc = wantAt(wx, wz);
    if (!npc) break;
    await stayAlive();
    const idx = npc.index, nm = npc.name, lv = npc.combatLevel ?? 0;
    const r = await bot.attack(npc);
    if (!r.success) { log.push('fail ' + nm + ' ' + r.reason); SKIP.add(nm); break; }
    try {
      await sdk.waitForCondition(s => !s.nearbyNpcs.some(n => n.index === idx), 40_000);
      KILLED[nm] = lv; SKIP.add(nm); log.push('KILL ' + nm + ' ' + lv);
      await lootFood();
    } catch { log.push('timeout ' + nm); }
    if (SKIP.has(nm) && Object.keys(KILLED).length >= 6) { /* keep going for more names */ }
  }
}
const st = sdk.getState();
return { killed: KILLED, log, combat: st.player.combatLevel, hp: st.player.hitpoints, pos: [st.player.worldX, st.player.worldZ], minLeft: Math.round((new Date('2026-10-22T20:10:58.651Z').getTime() - Date.now()) / 1000) };

