const KILLED: Record<string, number> = { Rat: 1, Man: 2, Woman: 2, "Giant rat": 3, Goblin: 5, "Giant spider": 2, Spider: 1, Duck: 1, Cow: 2, Imp: 2, Farmer: 7, Chicken: 1 };
const done = new Set(Object.keys(KILLED));
const BRAVO = new Set(["Al-Kharid warrior", "Scorpion"]);
function pick() {
  const st = sdk.getState();
  const cb = st.player.combatLevel;
  let best: any = null;
  for (const n of st.nearbyNpcs) {
    if (!n.reachable || !n.optionsWithIndex.some(o => /attack/i.test(o.text))) continue;
    const lv = n.combatLevel ?? 0;
