async function hunt(tries: number, tag: string) {
  const out: string[] = [];
  for (let i = 0; i < tries; i++) {
    if (hp() < 10) { out.push('flee'); await sdk.waitForTicks(24); if (hp() < 9) break; }
    const st = sdk.getState();
    let best: any = null;
    for (const n of st.nearbyNpcs) {
      if (!n.reachable || !n.optionsWithIndex.some(o => /attack/i.test(o.text))) continue;
      const lv = n.combatLevel ?? 0;
      if (lv > 18 || banned.has(n.name)) continue;
      if (mine.has(n.name) && KILLED[n.name] >= lv) continue;
      const sc = Math.log(1 + lv) * 14 - n.distance + (!mine.has(n.name) ? 16 : 0);
      if (!best || sc > best.score) best = { score: sc, npc: n };
    }
    if (!best) break;
    const npc = best.npc, idx = npc.index, nm = npc.name, lv = npc.combatLevel ?? 0;
    const r = await bot.attack(npc);
    if (!r.success) { out.push('fail ' + nm); break; }
    try {
      await sdk.waitForCondition(s => s.player.hitpoints === 0 || !s.nearbyNpcs.some(n => n.index === idx), 34_000);
    } catch { out.push('tout ' + nm + ' ' + lv); continue; }
    if (sdk.getState().player.hitpoints === 0) { out.push('DIED ' + nm + ' ' + lv); return out; }
    if ((KILLED[nm] ?? 0) < lv) KILLED[nm] = lv;
    mine.add(nm);
    out.push('KILL ' + nm + ' ' + lv + ' hp' + hp());
    console.log(tag, 'KILL', nm, lv, 'hp', hp());
  }
  return out;
}
