const KILLED: Record<string, number> = { Rat: 1, Man: 2, Woman: 2, "Giant rat": 3, Goblin: 5, "Giant spider": 2, Spider: 1, Duck: 1, Cow: 2, Imp: 2, Farmer: 7, Chicken: 1, Unicorn: 15, Mugger: 6, Thief: 16, Highwayman: 5, "Dark wizard": 7 };
const mine = new Set(Object.keys(KILLED));
function hp() { return sdk.getState().player.hitpoints; }
function soloTarget(minLv: number, maxLv: number, names: RegExp[]) {
  const st = sdk.getState();
  let best: any = null;
  for (const n of st.nearbyNpcs) {
    if (!n.reachable || !n.optionsWithIndex.some(o => /attack/i.test(o.text))) continue;
    const lv = n.combatLevel ?? 0;
    if (lv < minLv || lv > maxLv) continue;
    if (!names.some(r => r.test(n.name))) continue;
    if (mine.has(n.name) && KILLED[n.name] >= lv) continue;
    const others = st.nearbyNpcs.filter(o => o.index !== n.index && (o.combatLevel ?? 0) >= 6 && Math.abs(o.x - n.x) + Math.abs(o.z - n.z) < 7);
    if (others.length > 0) continue;
    const sc = Math.log(1 + lv) * 20 - n.distance;
    if (!best || sc > best.score) best = { score: sc, npc: n };
  }
  return best ? best.npc : null;
}
async function tryKill(npc: any) {
  const idx = npc.index, nm = npc.name, lv = npc.combatLevel ?? 0;
  const r = await bot.attack(npc);
  if (!r.success) return 'fail ' + nm + ' ' + r.reason;
  try {
    await sdk.waitForCondition(s => s.player.hitpoints === 0 || !s.nearbyNpcs.some(n => n.index === idx), 32_000);
  } catch { return 'tout ' + nm + ' ' + lv; }
  if (sdk.getState().player.hitpoints === 0) return 'DIED ' + nm + ' ' + lv;
  if ((KILLED[nm] ?? 0) < lv) KILLED[nm] = lv;
  mine.add(nm);
  return 'KILL ' + nm + ' ' + lv + ' hp' + hp();
}
