const out: string[] = [];
async function tryReach(re: RegExp, label: string, secs: number) {
  const stop = Date.now() + secs * 1000;
  while (Date.now() < stop) {
    const st = sdk.getState();
    const npc = st.nearbyNpcs.find(n => re.test(n.name));
    if (!npc) { out.push(label + ' GONE'); return true; }
    const r = await bot.attack(npc, 8_000).catch((e: any) => ({ success: false, message: e.message }));
    if (!r.success) out.push(label + ':' + (r as any).reason);
    await sdk.waitForTicks(12);
    const s2 = sdk.getState();
    out.push(label + ' hp' + s2.player.hitpoints + ' skelHp?' + (s2.nearbyNpcs.find(n => re.test(n.name))?.healthPercent ?? 'gone') + ' inCombat:' + s2.player.combat.inCombat);
    if ((s2.player.hitpoints ?? 0) === 0) { out.push('DEAD'); return false; }
    if (!s2.nearbyNpcs.some(n => re.test(n.name))) { out.push(label + ' KILLED lvl' + (npc.combatLevel ?? '?')); return true; }
  }
  return false;
}
